apply(from = rootProject.file("gradle/seeds.gradle.kts"))//注入

@Suppress("UNCHECKED_CAST")
val seed = rootProject.extra["seedFn"] as (String, String) -> String

@Suppress("UNCHECKED_CAST")
val SEEDS = rootProject.extra["seedIndex"] as List<List<String>>

@Suppress("UNCHECKED_CAST")
val seedLiteral = rootProject.extra["seedLiteralFn"] as (String, String) -> String

val baiStringFogKey: String = seed("stringfog.key", "bai-stringfog-placeholder-key")

val baiAesSeed: String? = seed("baicodex.aes.key", "").takeIf { s ->
    s.isNotBlank() && s.all { it.isLetterOrDigit() || it == '.' || it == '_' || it == '-' }
}

val baiHost: String = seed("baicodex.host", "").trimEnd('/').takeIf { it.startsWith("http") } ?: ""

val baiBkKey: String = seed("baicodex.backup.key", "").takeIf { s ->
    s.isNotBlank() && s.all { it.isLetterOrDigit() || it == '.' || it == '_' || it == '-' }
} ?: "baicodex-backup-placeholder"

val miotClientId: String = seed("miot.client.id", "").takeIf { s -> s.length in 6..32 && s.all { it.isDigit() } } ?: ""

val miotRedirect: String = seed("miot.redirect", "").takeIf { s -> s.startsWith("http://") || s.startsWith("https://") } ?: ""

val miotRegion: String = seed("miot.region", "cn").takeIf { s ->
    s.isNotEmpty() && s.length <= 10 && s.all { it.isLowerCase() || it.isDigit() }
} ?: "cn"

android {
    namespace = "b.ai"
    compileSdk = 37
    ndkVersion = "28.2.13676358"

    defaultConfig {
        applicationId = "b.ai"
        minSdk = 24
        targetSdk = 34
        versionCode = 47
        versionName = "1.17.0"

        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
        buildConfigField("String", "BAI_HOST", "\"$baiHost\"")
        buildConfigField("String", "BAI_BK_KEY", "\"$baiBkKey\"")
        buildConfigField("String", "MIOT_CLIENT_ID", "\"$miotClientId\"")
        buildConfigField("String", "MIOT_REDIRECT", "\"$miotRedirect\"")
        buildConfigField("String", "MIOT_REGION", "\"$miotRegion\"")
        //种子注入：表里每一行都出一个 BuildConfig 字段，缺键就是空串
        SEEDS.forEach { row -> buildConfigField("String", row[0], seedLiteral(row[1], "")) }
        ndk {
            abiFilters += listOf("arm64-v8a", "armeabi-v7a")
        }
        
        if (baiAesSeed != null) {
            externalNativeBuild {
                cmake { arguments.add("-DBAI_KEY_HEX=$baiAesSeed") }
            }
        }
    } //默认配置

    externalNativeBuild {
        cmake {
            path = file("src/main/cpp/CMakeLists.txt")
        }
    } //native 构建

    buildFeatures {
        compose = true
        buildConfig = true
    }
    lint {
        checkReleaseBuilds = false
        abortOnError = false
    } //关掉 lintVital 检查

    buildTypes {
        release {
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "proguard-rules.pro"
            )
        }
        debug {
            isMinifyEnabled = false
        }
    } //releaseR8
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    packaging {
        jniLibs {
            useLegacyPackaging = true
            //libOpenCL.so 只是链接期桩（从设备 /vendor 拉的），运行期由系统 linker 提供；
            //打进 APK 会让 App 加载到私有目录那份，在 Android 10+ 的命名空间里反而受限
            excludes += "**/libOpenCL.so"
        }
    }
    kotlin {
        compilerOptions {
            jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.fromTarget("17"))
        }
    }
}

